// Package aws provides a Testcontainers module for AWS Emulator.
package aws

import (
	"bufio"
	"context"
	"crypto/tls"
	"crypto/x509"
	"errors"
	"fmt"
	"io"
	"path"
	"strings"

	"github.com/testcontainers/testcontainers-go"
	"github.com/testcontainers/testcontainers-go/wait"
)

const (
	port           = "9297/tcp"
	home           = "/tmp/testcontainers-aws"
	stateDirectory = home + "/.aws/emulator/9297"
)

// Container represents an AWS Emulator container.
type Container struct {
	testcontainers.Container
}

// Credentials contains the keys generated by this emulator instance.
// These keys are for the emulator only and cannot authenticate to AWS.
type Credentials struct {
	AccessKeyID     string
	SecretAccessKey string
}

// Run starts AWS Emulator with HTTPS and request authentication enabled.
// The image must have an aws-emulator entrypoint and support the --bind,
// --port and --auth flags. The module uses HOME=/tmp/testcontainers-aws and
// container port 9297 to locate the generated credentials and certificate.
func Run(ctx context.Context, img string, opts ...testcontainers.ContainerCustomizer) (*Container, error) {
	moduleOpts := make([]testcontainers.ContainerCustomizer, 0, 4+len(opts))
	moduleOpts = append(moduleOpts,
		testcontainers.WithEnv(map[string]string{"HOME": home}),
		testcontainers.WithCmd("--bind", "0.0.0.0", "--port", "9297", "--auth", "on"),
		testcontainers.WithExposedPorts(port),
		// The certificate is generated at startup. Bootstrap readiness before
		// retrieving it; clients use TLSConfig to verify subsequent requests.
		testcontainers.WithWaitStrategy(wait.ForHTTP("/__admin/health").WithPort(port).WithTLS(true).WithAllowInsecure(true)),
	)
	moduleOpts = append(moduleOpts, opts...)
	ctr, err := testcontainers.Run(ctx, img, moduleOpts...)
	var c *Container
	if ctr != nil {
		c = &Container{Container: ctr}
	}
	if err != nil {
		return c, fmt.Errorf("run aws emulator: %w", err)
	}
	return c, nil
}

// EndpointURL returns the HTTPS API endpoint using the dynamically mapped host port.
func (c *Container) EndpointURL(ctx context.Context) (string, error) {
	return c.PortEndpoint(ctx, port, "https")
}

// CACertificate returns this instance's generated certificate in PEM format.
func (c *Container) CACertificate(ctx context.Context) ([]byte, error) {
	return c.readFile(ctx, "ca.pem")
}

// TLSConfig returns a configuration that trusts only this emulator's certificate.
// The emulator's certificate always includes localhost. Verifying that name also
// supports Docker hosts reached through another IP address or hostname.
func (c *Container) TLSConfig(ctx context.Context) (*tls.Config, error) {
	cert, err := c.CACertificate(ctx)
	if err != nil {
		return nil, err
	}
	pool := x509.NewCertPool()
	if !pool.AppendCertsFromPEM(cert) {
		return nil, errors.New("aws emulator: invalid CA certificate")
	}
	return &tls.Config{RootCAs: pool, ServerName: "localhost", MinVersion: tls.VersionTLS12}, nil
}

// Credentials returns this instance's generated authentication keys.
func (c *Container) Credentials(ctx context.Context) (Credentials, error) {
	data, err := c.readFile(ctx, "emulator_credentials")
	if err != nil {
		return Credentials{}, err
	}
	return parseCredentials(string(data))
}

// WithDisableTelemetry disables AWS Emulator's usage telemetry.
func WithDisableTelemetry() testcontainers.CustomizeRequestOption {
	return testcontainers.WithEnv(map[string]string{"EMULATOR_TELEMETRY": "off"})
}

func (c *Container) readFile(ctx context.Context, name string) ([]byte, error) {
	r, err := c.CopyFileFromContainer(ctx, path.Join(stateDirectory, name))
	if err != nil {
		return nil, fmt.Errorf("aws emulator: copy %s: %w", name, err)
	}
	defer r.Close()
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("aws emulator: read %s: %w", name, err)
	}
	return data, nil
}

// parseCredentials reads the emulator's generated shared-credentials file,
// rather than loading credentials from the host's AWS environment or profiles.
func parseCredentials(data string) (Credentials, error) {
	var credentials Credentials
	var inDefault bool
	scanner := bufio.NewScanner(strings.NewReader(data))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if strings.HasPrefix(line, "[") {
			inDefault = line == "[default]"
			continue
		}
		if !inDefault || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		key, value, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		switch strings.TrimSpace(key) {
		case "aws_access_key_id":
			credentials.AccessKeyID = strings.TrimSpace(value)
		case "aws_secret_access_key":
			credentials.SecretAccessKey = strings.TrimSpace(value)
		}
	}
	if err := scanner.Err(); err != nil {
		return Credentials{}, fmt.Errorf("aws emulator: scan credentials: %w", err)
	}
	if credentials.AccessKeyID == "" || credentials.SecretAccessKey == "" {
		return Credentials{}, errors.New("aws emulator: missing default credentials")
	}
	return credentials, nil
}
